CREATE TRIGGER trg_admin_audit_no_delete BEFORE DELETE ON admin_audit_log BEGIN SELECT RAISE(ABORT, 'IMMUTABLE_LEDGER'); END;
CREATE TRIGGER trg_admin_audit_no_update BEFORE UPDATE ON admin_audit_log BEGIN SELECT RAISE(ABORT, 'IMMUTABLE_LEDGER'); END;
CREATE TRIGGER trg_inventory_ledger_no_delete BEFORE DELETE ON inventory_ledger BEGIN SELECT RAISE(ABORT, 'IMMUTABLE_LEDGER'); END;
